insert into public.councils as c
  (slug, name, council_type, region, nation, official_code, website_url, logo_url, logo_type, logo_source_url)
select
  slug, name, council_type, region,
  case left(official_code, 1) when 'E' then 'England' when 'S' then 'Scotland' when 'W' then 'Wales' when 'N' then 'Northern Ireland' end,
  official_code,
  'https://' || host || '/',
  case when file is not null then 'https://commons.wikimedia.org/wiki/Special:FilePath/' || file end,
  case kind when 'L' then 'logo' when 'A' then 'coat_of_arms' end,
  case when file is not null then 'https://commons.wikimedia.org/wiki/File:' || file end
from v
on conflict (slug) do update set
  council_type = excluded.council_type,
  region = excluded.region,
  nation = excluded.nation,
  official_code = excluded.official_code,
  website_url = coalesce(c.website_url, excluded.website_url),
  logo_url = excluded.logo_url,
  logo_type = excluded.logo_type,
  logo_source_url = excluded.logo_source_url,
  updated_at = now();

update public.councils set nation = 'England' where nation is null;
